<?php declare(strict_types=1); namespace Tests\Unit\Services; use App\Services\DatabaseNativeClientCommandBuilder; use PHPUnit\Framework\TestCase;
final class DatabaseNativeClientCommandBuilderTest extends TestCase{public function testItBuildsExactProfilesWithoutCredentials():void{$b=new DatabaseNativeClientCommandBuilder;$m=$b->build('backup','mysql','mysqldump','C:\\private.cnf','tgh_test','utf8mb4');self::assertSame(['--defaults-extra-file=C:\\private.cnf','--single-transaction','--quick','--skip-lock-tables','--column-statistics=0','--no-tablespaces','--hex-blob','--default-character-set=utf8mb4','tgh_test'],$m['arguments']);$d=$b->build('backup','mariadb','mariadb-dump','C:\\private.cnf','tgh_test','utf8mb4');self::assertSame(['--defaults-extra-file=C:\\private.cnf','--single-transaction','--quick','--skip-lock-tables','--hex-blob','--default-character-set=utf8mb4','tgh_test'],$d['arguments']);self::assertSame(['--defaults-extra-file=C:\\private.cnf','--default-character-set=utf8mb4','tgh_test'],$b->build('restore','mysql','mysql','C:\\private.cnf','tgh_test','utf8mb4')['arguments']);}}
